// ---- Helpers: keep these. The tests use ListNode, fromArray and toArray. ----
class ListNode {
  constructor(val, next = null) {
    this.val = val;
    this.next = next;
  }
}

// fromArray([1, 2, 3]) builds 1 -> 2 -> 3 and returns the head (null for []).
function fromArray(values) {
  let head = null;
  for (let i = values.length - 1; i >= 0; i--) {
    head = new ListNode(values[i], head);
  }
  return head;
}

// toArray(head) walks the list and returns [1, 2, 3]. Handy for console.log too.
function toArray(head) {
  const values = [];
  let node = head;
  while (node) {
    values.push(node.val);
    if (values.length > 10000) throw new Error('list is too long: did you accidentally create a cycle?');
    node = node.next;
  }
  return values;
}
// ---- End of helpers ----

function removeNthFromEnd(head, n) {
  const dummy = new ListNode(0, head); // lets us remove the real head like any other node
  let fast = dummy;
  let slow = dummy;
  // Move fast n + 1 steps ahead, so the gap between slow and fast is n nodes.
  for (let step = 0; step <= n; step++) {
    fast = fast.next;
  }
  // Move both until fast falls off the end. slow is now just BEFORE the node to remove.
  while (fast !== null) {
    fast = fast.next;
    slow = slow.next;
  }
  slow.next = slow.next.next;
  return dummy.next;
}
